#' Time Intervals (Python UTC Core)
#'
#' 
#' @param data .
#' @param dx_date .
#' @param fu_date .
#' @param time_format .
#' @param output_unit .
#' @param time_basis .
#' @param use_landmark .
#' @param landmark_time .
#' @param remove_negative .
#' @param remove_extreme .
#' @param extreme_multiplier .
#' @param confidence_level .
#' @param preview_rows .
#' @param include_quality_metrics .
#' @param show_summary .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$statistics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$uncertainty} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$quality} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rawQuality} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$report} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$calculated_time} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pytimeinterval <- function(
    data,
    dx_date = NULL,
    fu_date = NULL,
    time_format = "ymd",
    output_unit = "months",
    time_basis = "standardized",
    use_landmark = FALSE,
    landmark_time = 6,
    remove_negative = FALSE,
    remove_extreme = FALSE,
    extreme_multiplier = 2,
    confidence_level = 95,
    preview_rows = 20,
    include_quality_metrics = FALSE,
    show_summary = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pytimeinterval requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dx_date)) dx_date <- jmvcore::resolveQuo(jmvcore::enquo(dx_date))
    if ( ! missing(fu_date)) fu_date <- jmvcore::resolveQuo(jmvcore::enquo(fu_date))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dx_date), dx_date, NULL),
            `if`( ! missing(fu_date), fu_date, NULL))


    options <- pytimeintervalOptions$new(
        dx_date = dx_date,
        fu_date = fu_date,
        time_format = time_format,
        output_unit = output_unit,
        time_basis = time_basis,
        use_landmark = use_landmark,
        landmark_time = landmark_time,
        remove_negative = remove_negative,
        remove_extreme = remove_extreme,
        extreme_multiplier = extreme_multiplier,
        confidence_level = confidence_level,
        preview_rows = preview_rows,
        include_quality_metrics = include_quality_metrics,
        show_summary = show_summary,
        showConsole = showConsole)

    analysis <- pytimeintervalClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

